<script lang="ts">
	import { CheckCircle2 } from '@lucide/svelte';
	import BmsCompactCellResistanceTable from './BmsCompactCellResistanceTable.svelte';
	import BmsCompactCellVoltageTable from './BmsCompactCellVoltageTable.svelte';
	import type { InitialBaselineStageFiveActions, InitialBaselineStageFiveModel } from './initial-baseline-stage-form';

	let { model, actions }: { model: InitialBaselineStageFiveModel; actions: InitialBaselineStageFiveActions } = $props();
	let editable = $derived(!model.readOnly && !model.busy);
</script>

<section class="recovery-workflow" data-mode={model.mode}>
	<label class="confirm"><input type="checkbox" checked={model.recoveryMcbClosed} disabled={!editable || model.recoveryStarted} onchange={(event) => actions.setRecoveryMcbClosed(event.currentTarget.checked)} /><span><strong>Confirm charger DC MCB is closed</strong><small>Reconnect the charger before starting the recovery charge.</small></span></label>
	{#if model.recoveryMcbClosed}
		<div class="charge-targets"><div><span>Vboost target</span><strong>{model.boostVoltage.toFixed(1)} V</strong><small>{model.boostVoltagePerCell.toFixed(2)} V/cell × {model.cellCount} cells</small></div><div><span>Vfloat target</span><strong>{model.floatVoltage.toFixed(1)} V</strong><small>{model.floatVoltagePerCell.toFixed(2)} V/cell × {model.cellCount} cells</small></div><div><span>Current limit</span><strong>{model.currentLimit.toFixed(1)} A</strong><small>Configured for this event</small></div></div>
		<label class="confirm"><input type="checkbox" checked={model.recoverySettingsVerified} disabled={!editable || model.recoveryStarted} onchange={(event) => actions.setRecoverySettingsVerified(event.currentTarget.checked)} /><span><strong>Verify recovery charge settings</strong><small>Targets match the verified configuration for this event.</small></span></label>
	{/if}
	{#if model.recoveryMcbClosed && model.recoverySettingsVerified && !model.recoveryStarted}<button class="secondary start" disabled={!editable} onclick={actions.startRecovery}>Start recovery charge</button>{/if}
	{#if model.recoveryStarted}<div class:ready={model.recoveryChargeComplete} class="charge-status"><div class="status-head"><div><span>Recovery boost charge</span><strong>{model.recoveryChargeComplete ? 'Vboost target reached' : 'Charging to Vboost'}</strong></div><b>{model.recoveryBoostVoltage?.toFixed(1) ?? '—'} V / {model.boostVoltage.toFixed(1)} V</b></div><div class="progress"><i style={`width:${model.recoveryProgress}%`}></i></div>{#if !model.recoveryChargeComplete}<div class="waiting"><i></i>{model.mode === 'demo' ? 'Recovery charging · demo time accelerated' : 'Waiting for the authoritative recovery process'}</div>{/if}</div>{/if}
	{#if model.recoveryChargeComplete && !model.recoveryFloatStarted}<div class="auto-transition"><CheckCircle2 size={16} />Vboost reached — waiting for the Float process.</div>{/if}
	{#if model.recoveryFloatStarted && !model.recoveryFloatReached}<div class="charge-status"><div class="status-head"><div><span>Float charge</span><strong>Settling to Vfloat</strong></div><b>{model.recoveryFloatVoltage?.toFixed(1) ?? '—'} V / {model.floatVoltage.toFixed(1)} V</b></div><div class="progress float-progress"><i style={`width:${model.recoveryFloatProgress}%`}></i></div><div class="waiting"><i></i>Charger output is reducing to the configured Vfloat target</div></div>{/if}
	{#if model.recoveryFloatReached}<div class:ready={model.recoveryFloatComplete} class="float-stable"><div class="status-head"><div><span>Float stable mode</span><strong>{model.recoveryFloatComplete ? 'Stable window complete' : 'Holding within Float range'}</strong></div><b>{model.recoveryFloatStableProgress}%</b></div><div class="progress float-progress"><i style={`width:${model.recoveryFloatStableProgress}%`}></i></div><div class="float-metrics"><div><span>Current voltage</span><strong>{model.recoveryFloatVoltage?.toFixed(1) ?? '—'} V</strong></div><div><span>Current charge</span><strong>{model.recoveryFloatCurrentA?.toFixed(2) ?? '—'} A</strong></div><div><span>Stable duration</span><strong>{model.recoveryFloatElapsedSeconds} / {model.recoveryFloatStableSeconds} sec</strong><small>{model.mode === 'demo' ? 'Demo uses a real-time 60-second window' : 'Persisted backend process status'}</small></div></div></div>{/if}
	{#if model.recoveryFloatComplete}<label class="confirm"><input type="checkbox" checked={model.recoveryFloatConfirmed} disabled={!editable || model.recoveryFloatConfirmed} onchange={(event) => actions.setRecoveryFloatConfirmed(event.currentTarget.checked)} /><span><strong>Confirm Float condition is stable</strong><small>Review the stable-window voltage and current before recording baseline measurements.</small></span></label>{/if}

	{#if model.recoveryFloatConfirmed}
		<BmsCompactCellResistanceTable cells={model.resistanceCells} expectedCount={model.cellCount} description={`${model.resistanceCells.length} of ${model.cellCount} cells recorded after the Float stable window.`} />
		<label class="confirm"><input type="checkbox" checked={model.resistanceConfirmed} disabled={!editable || model.resistanceConfirmed} onchange={(event) => actions.setResistanceConfirmed(event.currentTarget.checked)} /><span><strong>Confirm every cell resistance is recorded</strong><small>Average resistance: {model.averageResistanceMohm} mΩ. Review the IR outlier warning before continuing.</small></span></label>
	{/if}

	{#if model.recoveryFloatConfirmed && model.resistanceConfirmed}
		<section class="baseline-measurements"><header><div><span>Baseline measurements — no load</span><strong>Record these values before connecting the load.</strong></div><small>Required</small></header>
			<div class="measurement-grid"><label><span>Float current (mA)</span><input type="number" min="0" value={model.floatCurrent} disabled={!editable || model.mode === 'real'} oninput={(event) => actions.setFloatCurrent(event.currentTarget.value)} /><input type="checkbox" checked={model.floatCurrentConfirmed} disabled={!editable || !model.floatCurrent.trim() || model.floatCurrent === '—'} onchange={(event) => actions.setFloatCurrentConfirmed(event.currentTarget.checked)} /></label>{#if model.floatCurrentConfirmed}<label><span>Midpoint voltage (V)</span><input type="number" step="0.1" value={model.midpointVoltage} disabled={!editable || model.mode === 'real'} oninput={(event) => actions.setMidpointVoltage(event.currentTarget.value)} /><input type="checkbox" checked={model.midpointConfirmed} disabled={!editable || !model.midpointVoltage.trim() || model.midpointVoltage === '—'} onchange={(event) => actions.setMidpointConfirmed(event.currentTarget.checked)} /></label>{/if}{#if model.midpointConfirmed}<label><span>AC ripple — no load (V)</span><input type="number" step="0.1" value={model.rippleNoLoad} disabled={!editable || model.rippleNoLoadConfirmed} oninput={(event) => actions.setRippleNoLoad(event.currentTarget.value)} /><input type="checkbox" checked={model.rippleNoLoadConfirmed} disabled={!editable || !model.rippleNoLoad.trim()} onchange={(event) => actions.setRippleNoLoadConfirmed(event.currentTarget.checked)} /></label>{/if}</div>
		</section>
	{/if}
	{#if model.floatCurrentConfirmed && model.midpointConfirmed && model.rippleNoLoadConfirmed}<label class="confirm"><input type="checkbox" checked={model.loadConnected} disabled={!editable || model.loadConnected} onchange={(event) => actions.setLoadConnected(event.currentTarget.checked)} /><span><strong>Confirm load is connected</strong><small>Connect the operating load before taking the loaded ripple reading.</small></span></label>{/if}
	{#if model.loadConnected}<div class="loaded-ripple"><span>AC ripple — with load (V)</span><input type="number" min="0" step="0.1" value={model.rippleWithLoad} disabled={!editable || model.rippleWithLoadConfirmed} oninput={(event) => actions.setRippleWithLoad(event.currentTarget.value)} /><label><input type="checkbox" checked={model.rippleWithLoadConfirmed} disabled={!editable || model.rippleWithLoadConfirmed || !model.rippleWithLoad.trim()} onchange={(event) => actions.setRippleWithLoadConfirmed(event.currentTarget.checked)} />Confirm measured</label></div>{/if}
	{#if model.rippleWithLoadConfirmed}<label class="confirm"><input type="checkbox" checked={model.chargerMcbOpen} disabled={!editable || model.chargerMcbOpen} onchange={(event) => actions.setChargerMcbOpen(event.currentTarget.checked)} /><span><strong>Confirm charger DC MCB is open</strong><small>Isolate the charger before the persisted Voc snapshot is captured.</small></span></label>{/if}
	{#if model.chargerMcbOpen && !model.vocSampleId}<div class="waiting voc-wait"><i></i>{model.vocLoading ? 'Loading persisted Voc snapshot…' : 'Waiting for the persisted Voc snapshot…'}</div>{/if}
	{#if model.vocError}<div class="warning">{model.vocError}. Live telemetry is not used as a fallback.</div>{/if}
	{#if model.vocSampleId}
		<section class="voc-snapshot"><div class="data-heading"><div><h4>Persisted Voc baseline</h4><p>{model.vocCapturedAt ?? 'Measurement time not recorded'} · sample #{model.vocSampleId}</p></div><span>FINAL</span></div><div class="voc-metrics"><article><span>String voltage</span><strong>{model.vocStringVoltage?.toFixed(3) ?? '—'} V</strong><small>Persisted FINAL_SNAPSHOT</small></article><article><span>Cell voltages</span><strong>{model.vocCells.filter((cell) => cell.voltage !== null).length}/{model.cellCount}</strong><small>Exact persisted sample</small></article></div><BmsCompactCellVoltageTable cells={model.vocCells} expectedCount={model.cellCount} title="Cell Data · Open-circuit Voltage" ariaLabel="Persisted Initial Baseline Voc cell voltages" emptyMessage="No persisted Voc cell voltage is available." />
			<label class="confirm"><input type="checkbox" checked={model.vocConfirmed} disabled={!editable || model.vocConfirmed} onchange={(event) => actions.setVocConfirmed(event.currentTarget.checked)} /><span><strong>Confirm persisted Voc baseline data</strong><small>Confirm the exact string voltage and per-cell voltage snapshot shown above.</small></span></label>
		</section>
	{/if}
</section>

